use std::io
use std::collections::HashMap

fn process(parts: Vec<string>, accts: HashMap<string, int>) -> string {
    let cmd = parts[0]
    if cmd == "balance" {
        if parts.len() < 2 { return "error: invalid amount" }
        if !accts.contains_key(parts[1]) { return "error: unknown account ${parts[1]}" }
        return "${accts[parts[1]]}"
    }
    if cmd == "open" {
        let amt: int = parts[2].parse::<int>().unwrap_or(0)
        if amt < 0 { return "error: invalid amount" }
        if accts.contains_key(parts[1]) { return "error: duplicate account" }
        accts.insert(parts[1], amt)
        return "ok"
    }
    if cmd == "deposit" || cmd == "withdraw" {
        let amt: int = parts[2].parse::<int>().unwrap_or(0)
        if amt <= 0 { return "error: invalid amount" }
        if !accts.contains_key(parts[1]) { return "error: unknown account ${parts[1]}" }
        let bal = accts[parts[1]]
        if cmd == "deposit" {
            accts.insert(parts[1], bal + amt)
            return "ok"
        }
        if amt > bal { return "error: insufficient funds" }
        accts.insert(parts[1], bal - amt)
        return "ok"
    }
    if cmd == "transfer" {
        let amt: int = parts[3].parse::<int>().unwrap_or(0)
        if amt <= 0 { return "error: invalid amount" }
        if !accts.contains_key(parts[1]) { return "error: unknown account ${parts[1]}" }
        if !accts.contains_key(parts[2]) { return "error: unknown account ${parts[2]}" }
        if parts[1] == parts[2] { return "error: same account" }
        let bal = accts[parts[1]]
        if amt > bal { return "error: insufficient funds" }
        accts.insert(parts[1], bal - amt)
        let other = accts[parts[2]]
        accts.insert(parts[2], other + amt)
        return "ok"
    }
    ""
}

fn main() {
    let mut accts: HashMap<string, int> = HashMap::new()
    loop {
        let line = match io::read_line() {
            Ok(l) => l,
            Err(_) => break,
        }
        if line.len() == 0 { break }
        let parts: Vec<string> = line.split_whitespace().collect()
        if parts.len() == 0 { continue }
        let out = process(parts, accts)
        if out.len() > 0 { println(out) }
    }
    let mut names: Vec<string> = []
    for k in accts.keys() { names.push(k) }
    names.sort()
    for n in names {
        println("${n} ${accts[n]}")
    }
}

